    private static int GetIndex(int appearanceId) => appearanceId switch
        {
            110 => 0,
            112 => 1,
            113 => 2,
            116 => 3,
            118 => 4,
            121 => 5,
            119 => 6,
            120 => 7,
            _ => -1
        };

    internal static bool IsCorrected(int appearanceId) => GetIndex(appearanceId) >= 0;

    internal static bool HasTarget(string handModel, int appearanceId) => IsCorrected(appearanceId) &&
        !string.IsNullOrWhiteSpace(handModel) && HandGripCenters.ContainsKey(handModel);

    internal static GripVector GetTranslation(string handModel, int appearanceId, float sharedScale)
    {
        if (PowerGloveHandFitOverrides.TryGetTranslation(handModel, appearanceId, sharedScale, out var translation))
            return translation;
        var index = GetIndex(appearanceId);
        if (index < 0 || string.IsNullOrWhiteSpace(handModel) ||
            !HandGripCenters.TryGetValue(handModel, out var targets))
            return GripVector.Zero;

        // Scaling about the hook must not carry the physical grip out of the palm.
        return targets[index] - sharedScale * AuthoredGripCenters[index];
    }
